import itertools
A = [(1, 4), (3, 5), (0, 6), (5, 7), (3, 8), (5, 9), (6, 10), (8, 11), (8, 12), (2, 13), (12, 14)]
def fits(sel):
    sel = sorted(sel, key=lambda t: t[1]); return all(sel[i][1] <= sel[i + 1][0] for i in range(len(sel) - 1))
def best(iv): return max(k for k in range(len(iv) + 1) if any(fits(c) for c in itertools.combinations(iv, k)))
def by(iv, key):
    out = []
    for t in sorted(iv, key=key):
        if all(t[1] <= u[0] or u[1] <= t[0] for u in out): out.append(t)
    return out
def gen(n): return [((37 * i) % 200, (37 * i) % 200 + 5 + i % 7) for i in range(n)]
result = best(A)

